import assert from 'node:assert/strict';
import { Axiom, AxiomWithoutBatching } from '@axiomhq/js';
import { AxiomJSTransport, Logger } from '@axiomhq/logging';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Dub's Axiom logging (dubinc/dub 7e010136, apps/web/lib/axiom/axiom.ts and server.ts), on the token and dataset the
// World issued: AXIOM_TOKEN and AXIOM_DATASET.
assert.match(process.env.AXIOM_TOKEN ?? '', /^xaat-/);
assert.ok(process.env.AXIOM_DATASET);
const axiomClient = new Axiom({ token: process.env.AXIOM_TOKEN });
const logger = new Logger({ transports: [new AxiomJSTransport({ axiom: axiomClient, dataset: process.env.AXIOM_DATASET })] });
// the account's datasets, as a vendor-backed root reads them
const datasets = async () => (await new AxiomWithoutBatching({ token: process.env.AXIOM_TOKEN }).datasets.list()).map((d) => d.name);

if (process.argv[2] === 'readback') {
  // after the World resumes: the dataset is still the account's, read without writing
  assert.ok((await datasets()).includes(process.env.AXIOM_DATASET));
  console.log(JSON.stringify({ readback: process.env.AXIOM_DATASET }));
} else {
  const errors = [];
  axiomClient.onError = (e) => errors.push(e);
  // a route's request line and a job's refusal, flushed as Dub's handlers flush them
  logger.info('POST /api/resend/webhook 200 in 42ms', { route: '/api/resend/webhook' });
  logger.error('jobs.invalid_envelope', { error: 'Required at "jobName"' });
  await logger.flush();
  assert.deepEqual(errors, [], 'the batch was ingested');
  // the same ingest without batching answers its status: what the batch above was told
  const status = await new AxiomWithoutBatching({ token: process.env.AXIOM_TOKEN }).ingest(process.env.AXIOM_DATASET, [{ level: 'info', message: 'GET /api/links 200 in 7ms' }]);
  assert.equal(status.ingested, 1);
  assert.equal(status.failed, 0);
  assert.ok((await datasets()).includes(process.env.AXIOM_DATASET));
  console.log(JSON.stringify({ dataset: process.env.AXIOM_DATASET, ingested: status.ingested }));
}
